-- 의약품 축약본(1,000개판): 시나리오·페르소나 약 + 자주 쓰는 일반의약품 + 영양제와 부딪히는 약 + 영양 성분이 든 일반의약품 + 직접 추가한 약 (1003개)
-- 원본: database/drug.csv · database/drug_ingredient.csv (구조는 drug_csv/supabase/schema.sql과 같고 테이블 이름 앞에 new_)
-- Supabase SQL Editor에 전체를 붙여넣고 Run. 다시 실행하면 new_drug·new_drug_ingredient를 지우고 새로 만든다.
-- 03_new_nutrient_interaction.sql의 뷰·외래키가 new_drug을 참조하므로 cascade로 함께 지운다. 이 파일을 다시 실행했으면 03도 다시 실행한다.
-- 성분 3146행

begin;

create extension if not exists pg_trgm;   -- 약 이름 부분검색용

drop table if exists public.new_drug_ingredient;
drop table if exists public.new_drug cascade;

create table public.new_drug (
  item_seq         text primary key,   -- 품목기준코드
  name             text not null,      -- 제품명
  company          text,               -- 업체명
  category         text,               -- 구분 (전문/일반의약품)
  ingredient_count int,                -- 성분수
  ingredients_text text,               -- 성분 (화면 표시용)
  ingredients_en   text,               -- 성분_영문
  pick_reason      text                -- 축약본에 넣은 이유 (원본에 없는 열)
);

create table public.new_drug_ingredient (
  id              bigint generated always as identity primary key,
  item_seq        text not null references public.new_drug(item_seq) on delete cascade,
  ingredient_code text,                -- 성분코드 (영문 성분명만 있는 약은 비어 있음)
  ingredient_name text not null,       -- 성분명
  amount          numeric,             -- 함량
  amount_raw      text,                -- 함량 원문 ('250(역가)' 처럼 숫자만이 아닌 경우만)
  unit            text,                -- 단위
  source          text                 -- 출처
);


